#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/ztest.h>

#define GPIO_NODE DT_ALIAS(gpio_1)

#if !DT_NODE_HAS_STATUS(GPIO_NODE, okay)
#error "board specified node not found"
#endif

#define TEST_PIN 1

static void *gpio_get_direction_setup(void)
{
	const struct device *const port = DEVICE_DT_GET(GPIO_NODE);

	if (!device_is_ready(port)) {
		TC_PRINT("GPIO device %s is not ready", port->name);
		ztest_test_skip();
	}
	return NULL;
}

static void gpio_get_direction_teardown(void *data)
{
	const struct device *const port = DEVICE_DT_GET(GPIO_NODE);
	int ret;

	/* The disconnect function is optional */
	ret = gpio_pin_disconnect(port, TEST_PIN);
	zassert_true(ret == 0 || ret == -ENOSYS, "gpio_pin_disconnect() failed");
}

static void test_output(void)
{
	const struct device *const port = DEVICE_DT_GET(GPIO_NODE);
	int ret;
	gpio_port_pins_t pins_dir;

	/* Pin must be configured as input or output for gpio_pin_get_direction to succeed */
	ret = gpio_pin_configure(port, TEST_PIN, GPIO_OUTPUT);
	zassert_ok(ret, "gpio_pin_configure failed");

	ret = gpio_pin_get_direction(port, TEST_PIN, &pins_dir);
	zassert_ok(ret, "gpio_pin_get_direction failed");
	zassert_equal(pins_dir, BIT(TEST_PIN), "pin direction is not GPIO_OUTPUT");
}

static void test_input(void)
{
	const struct device *const port = DEVICE_DT_GET(GPIO_NODE);
	int ret;
	gpio_port_pins_t pins_dir;

	/* Pin must be configured as input or output for gpio_pin_get_direction to succeed */
	ret = gpio_pin_configure(port, TEST_PIN, GPIO_INPUT);
	zassert_ok(ret, "gpio_pin_configure failed");

	ret = gpio_pin_get_direction(port, TEST_PIN, &pins_dir);
	zassert_ok(ret, "gpio_pin_get_direction failed");
	zassert_equal(pins_dir, 0, "pin direction is not GPIO_INPUT");
}

static void test_not_supported(void)
{
	const struct device *const port = DEVICE_DT_GET(GPIO_NODE);
	int ret;
	gpio_port_pins_t pins_dir;

	/*
	 * The function is not supported if the pin is not configured for GPIO.
	 * So, this should fail.
	 */
	ret = gpio_pin_get_direction(port, TEST_PIN, &pins_dir);
	zassert_not_ok(ret, "gpio_pin_get_direction should have failed");
}

ZTEST_SUITE(gpio_get_direction, NULL, gpio_get_direction_setup, NULL, NULL,
	    gpio_get_direction_teardown);

ZTEST(gpio_get_direction, test_not_supported)
{
	test_not_supported();
}

ZTEST(gpio_get_direction, test_output)
{
	test_output();
}

ZTEST(gpio_get_direction, test_input)
{
	test_input();
}
